58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
67	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
68	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    /**
107	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
108	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
109	     */
110	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
111	        List<String> missing = new ArrayList<>();
112	        if (isBlank(ownerFieldsDto.getFirstName())) {
113	            missing.add("firstName");
114	        }
115	        if (isBlank(ownerFieldsDto.getLastName())) {
116	            missing.add("lastName");
117	        }
118	        if (isBlank(ownerFieldsDto.getAddress())) {
119	            missing.add("address");
120	        }
121	        if (isBlank(ownerFieldsDto.getCity())) {
122	            missing.add("city");
123	        }
124	        if (isBlank(ownerFieldsDto.getTelephone())) {
125	            missing.add("telephone");
126	        }
127	        if (!missing.isEmpty()) {
128	            throw new RequiredFieldsMissingException(missing);
129	        }
130	    }
131	
132	    private static boolean isBlank(String value) {
133	        return value == null || value.isBlank();
134	    }
135	
136	    /**
137	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
138	     * A leading {@code +} and its country code are kept as given; otherwise the country code
139	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
140	     * The result must carry 8 to 15 digits after the {@code +}. Returns the E.164 string to be
141	     * stored and returned.
142	     *
143	     * @param telephone the raw telephone as supplied by the caller
144	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
145	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
146	     */
147	    private static String normalizeTelephone(String telephone) {
148	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
149	        String e164;
150	        if (cleaned.startsWith("+")) {
151	            e164 = "+" + cleaned.substring(1);
152	        } else {
153	            String national = cleaned;
154	            if (national.startsWith("0")) {
155	                national = national.substring(1);
156	            }
157	            e164 = "+61" + national;
158	        }
159	        String digits = e164.substring(1);
160	        if (!digits.matches("\\d{8,15}")) {
161	            throw new InvalidTelephoneException(
162	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
163	        }
164	        return e164;
165	    }
166	
167	    /**
168	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
169	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
170	     *
171	     * @param email the raw email as supplied by the caller, may be {@code null}
172	     * @return the lower-cased email, or {@code null} when none was supplied
173	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
174	     */
175	    private static String normalizeEmail(String email) {
176	        if (email == null || email.isBlank()) {
177	            return null;
178	        }
179	        String trimmed = email.trim();
180	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
181	            throw new InvalidEmailException("Email must be a syntactically valid address");
182	        }
183	        return trimmed.toLowerCase(Locale.ROOT);
184	    }
185	
186	    /**
187	     * Rejects a create whose E.164 telephone is already used by any existing owner, so that
188	     * telephones stay unique across owners. Telephones are stored in E.164 form on create, so a
189	     * direct equality comparison of the E.164 values against the stored values is sufficient.
190	     *
191	     * @param normalizedTelephone the E.164 telephone of the owner being created
192	     * @throws DuplicateTelephoneException if another owner already uses this telephone
193	     */
194	    private void rejectDuplicateTelephone(String normalizedTelephone) {
195	        boolean inUse = this.clinicService.findAllOwners().stream()
196	            .anyMatch(existing -> normalizedTelephone.equals(existing.getTelephone()));
197	        if (inUse) {
198	            throw new DuplicateTelephoneException(
199	                "Telephone is already used by another owner");
200	        }
201	    }
202	
203	    /**
204	     * Rejects a create that would place the owner in a household already occupied by another owner,
205	     * i.e. one whose last name and address match the supplied values. The two fields are compared
206	     * case-insensitively after whitespace is collapsed (leading/trailing whitespace trimmed and each
207	     * run of internal whitespace reduced to a single space), so {@code '110 W.  Liberty St. '} and
208	     * {@code '110 w. liberty st.'} are treated as the same address. The caller may bypass this check
209	     * by setting {@code sharesHousehold} to {@code true}.
210	     *
211	     * @param lastName the last name of the owner being created
212	     * @param address the address of the owner being created
213	     * @throws DuplicateHouseholdException if another owner already shares this last name and address
214	     */
215	    private void rejectDuplicateHousehold(String lastName, String address) {
216	        String normalizedLastName = normalizeForHousehold(lastName);
217	        String normalizedAddress = normalizeForHousehold(address);
218	        boolean inHousehold = this.clinicService.findAllOwners().stream()
219	            .anyMatch(existing ->
220	                normalizedLastName.equals(normalizeForHousehold(existing.getLastName()))
221	                    && normalizedAddress.equals(normalizeForHousehold(existing.getAddress())));
222	        if (inHousehold) {
223	            throw new DuplicateHouseholdException(
224	                "An owner with the same last name and address already exists");
225	        }
226	    }
227	
228	    /**
229	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
230	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
231	     *
232	     * @param value the raw value, may be {@code null}
233	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
234	     */
235	    private static String normalizeForHousehold(String value) {
236	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
237	    }
238	
239	    /**
240	     * Builds the customer code assigned to an owner on create, formatted {@code '<LAST3>-<NNNN>'}
241	     * where {@code LAST3} is the upper-cased first three letters of the owner's last name and
242	     * {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than the current
243	     * number of owners, e.g. {@code 'SMI-0007'}.
244	     *
245	     * @param lastName the last name of the owner being created
246	     * @return the formatted customer code
247	     */
248	    private String nextCustomerCode(String lastName) {
249	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
250	        int sequence = this.clinicService.findAllOwners().size() + 1;
251	        return String.format("%s-%04d", last3, sequence);
252	    }
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
257	        Owner owner = this.clinicService.findOwnerById(ownerId);
258	        if (owner == null) {
259	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	        }
261	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
267	        validateRequiredFields(ownerFieldsDto);
268	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
269	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
270	        }
271	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
272	        rejectDuplicateTelephone(normalizedTelephone);
273	        ownerFieldsDto.setTelephone(normalizedTelephone);
274	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
275	        if (ownerFieldsDto.getRegistrationDate() == null) {
276	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
277	        }
278	        HttpHeaders headers = new HttpHeaders();
279	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
280	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getLastName()));
281	        this.clinicService.saveOwner(owner);
282	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
283	        headers.setLocation(UriComponentsBuilder.newInstance()
284	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
285	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
286	    }
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Override
290	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
291	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
292	        if (currentOwner == null) {
293	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
294	        }
295	        currentOwner.setAddress(ownerFieldsDto.getAddress());
296	        currentOwner.setCity(ownerFieldsDto.getCity());
297	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
298	        currentOwner.setLastName(ownerFieldsDto.getLastName());
299	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
300	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
301	        this.clinicService.saveOwner(currentOwner);
302	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
303	    }
304	
305	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
306	    @Transactional
307	    @Override
308	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
309	        Owner owner = this.clinicService.findOwnerById(ownerId);
310	        if (owner == null) {
311	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
312	        }
313	        this.clinicService.deleteOwner(owner);
314	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
315	    }
316	
317	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
318	    @Override
319	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
320	        Owner owner = this.clinicService.findOwnerById(ownerId);
321	        if (owner == null) {
322	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
323	        }
324	        HttpHeaders headers = new HttpHeaders();
325	        Pet pet = petMapper.toPet(petFieldsDto);
326	        owner.setId(ownerId);
327	        pet.setOwner(owner);
328	        pet.getType().setName(null);
329	        this.clinicService.savePet(pet);
330	        PetDto petDto = petMapper.toPetDto(pet);
331	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
332	            .buildAndExpand(pet.getId()).toUri());
333	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
334	    }
335	
336	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
337	    @Override
338	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
339	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
340	        if (currentOwner != null) {
341	            Pet currentPet = this.clinicService.findPetById(petId);
342	            if (currentPet != null) {
343	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
344	                currentPet.setName(petFieldsDto.getName());
345	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
346	                this.clinicService.savePet(currentPet);
347	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
348	            }
349	        }
350	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
351	    }
352	
353	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
354	    @Override
355	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
356	        HttpHeaders headers = new HttpHeaders();
357	        Visit visit = visitMapper.toVisit(visitFieldsDto);
358	        Pet pet = new Pet();
359	        pet.setId(petId);
360	        visit.setPet(pet);
361	        this.clinicService.saveVisit(visit);
362	        VisitDto visitDto = visitMapper.toVisitDto(visit);
363	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
364	            .buildAndExpand(visit.getId()).toUri());
365	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
366	    }
367	
368	
369	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
370	    @Override
371	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
372	        Owner owner = this.clinicService.findOwnerById(ownerId);
373	        if (owner != null) {
374	            Pet pet = owner.getPet(petId);
375	            if (pet != null) {
376	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
377	            }
378	        }
379	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
380	    }
381	}
